from pathlib import Path
import hashlib,json,re,tomllib
repo=Path('/home/codex/.codex/worktrees/46be/Proofs')
cache=Path('/home/codex/.codex/worktrees/62ff/Proofs')
cfg=tomllib.loads((repo/'lakefile.toml').read_text())
roots=[repo/x.get('srcDir','.') for x in cfg['lean_lib']]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
mods={}
def source(mod):
 for root in roots:
  p=root/(mod.replace('.','/')+'.lean')
  if p.exists():return p
 return None
def visit(mod):
 if mod in mods:return
 p=source(mod)
 if p is None:return
 imps=[]
 for line in p.read_text().splitlines():
  m=re.match(r'\s*(?:public\s+)?import\s+([A-Za-z0-9_.]+)',line)
  if m: imps.append(m[1])
 mods[mod]={'source':str(p),'source_sha256':sha(p),'imports':imps}
 for dep in imps:visit(dep)
for root in ['DiophantineConsistency.ObjectNaturalDiscrete','DiophantineConsistency.ObjectNaturalSemiring','DiophantineConsistency.WeightedExpressionDegree']:visit(root)
rows=[]
for mod,d in sorted(mods.items()):
 rel=Path(d['source']).relative_to(repo)
 cp=cache/rel
 obj=repo/'.lake/build/lib/lean'/(mod.replace('.','/')+'.olean')
 co=cache/'.lake/build/lib/lean'/(mod.replace('.','/')+'.olean')
 d.update(module=mod,cache_source_sha256=sha(cp),source_identical=sha(cp)==d['source_sha256'],current_object=str(obj),current_object_sha256=sha(obj),cache_object=str(co),cache_object_sha256=sha(co))
 rows.append(d)
metadata={k:{'current':sha(repo/k),'cache':sha(cache/k)} for k in ['lean-toolchain','lake-manifest.json']}
out={'metadata':metadata,'modules':rows}
Path('/tmp/object-current-deps-audit.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps({'custom_modules':len(rows),'missing':[(d['module'],d['source_identical'],bool(d['cache_object_sha256'])) for d in rows if not d['current_object_sha256']],'source_mismatches':[d['module'] for d in rows if not d['source_identical']],'metadata':metadata},indent=2))

from pathlib import Path
import hashlib, json, os, shutil, subprocess, tempfile, time

repo = Path('/home/codex/.codex/worktrees/46be/Proofs')
audit = json.loads(Path('/tmp/object-current-deps-audit.json').read_text())
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
fresh = {
    'DiophantineConsistency.ObjectPolynomial',
    'DiophantineConsistency.SyntaxCoefficients',
    'DiophantineConsistency.ObjectNaturalSemiring',
    'DiophantineConsistency.QuarticSyntax',
    'DiophantineConsistency.ObjectResidualSquares',
    'DiophantineConsistency.ObjectNaturalDiscrete',
}
rows = {r['module']: r for r in audit['modules']}
for name, hashes in audit['metadata'].items():
    if hashes['current'] != hashes['cache'] or sha(repo / name) != hashes['current']:
        raise RuntimeError('Metadata mismatch: ' + name)
for r in rows.values():
    if sha(r['source']) != r['source_sha256']:
        raise RuntimeError('Source changed: ' + r['module'])
    if r['module'] not in fresh and not r['current_object_sha256']:
        if not r['source_identical'] or not r['cache_object_sha256']:
            raise RuntimeError('Unauthenticated cached dependency: ' + r['module'])
        if sha(r['cache_object']) != r['cache_object_sha256']:
            raise RuntimeError('Cache object changed: ' + r['module'])

overlay = Path(tempfile.mkdtemp(prefix='object-current-deps-'))
Path('/tmp/object-current-overlay.txt').write_text(str(overlay) + '\n')
receipt = {'overlay': str(overlay), 'metadata': audit['metadata'],
           'scope': 'Private object-language closure; existing native and Mathlib prerequisites reused.',
           'modules': [], 'builds': []}
for mod, r in rows.items():
    row = dict(r)
    dest = overlay / (mod.replace('.', '/') + '.olean')
    dest.parent.mkdir(parents=True, exist_ok=True)
    if mod in fresh:
        row['mode'] = 'fresh-current-source'
    elif r['current_object_sha256']:
        if sha(r['current_object']) != r['current_object_sha256']:
            raise RuntimeError('Shared object changed: ' + mod)
        dest.symlink_to(r['current_object'])
        row['mode'] = 'reused-existing-shared-object'
        row['overlay_object_sha256'] = sha(dest)
    else:
        shutil.copyfile(r['cache_object'], dest)
        row['mode'] = 'copied-exact-source-cache-object-into-private-overlay'
        row['overlay_object_sha256'] = sha(dest)
    receipt['modules'].append(row)

env = os.environ.copy()
base_path = subprocess.check_output(['lake', 'env', 'printenv', 'LEAN_PATH'], cwd=repo, text=True).strip()
lean = subprocess.check_output(['lake', 'env', 'which', 'lean'], cwd=repo, text=True).strip()
env['LEAN_PATH'] = str(overlay) + ':' + base_path
seen = set()
order = []
def visit(mod):
    if mod in seen:
        return
    seen.add(mod)
    for dep in rows[mod]['imports']:
        if dep in rows:
            visit(dep)
    if mod in fresh:
        order.append(mod)
for mod in sorted(fresh):
    visit(mod)
for mod in order:
    r = rows[mod]
    dest = overlay / (mod.replace('.', '/') + '.olean')
    log = overlay / (mod.split('.')[-1] + '.log')
    command = [lean, '-M6000', '-j1', '-DElab.async=false', r['source'], '-o', str(dest)]
    print('BUILD', mod, flush=True)
    start = time.monotonic()
    with log.open('w') as output:
        result = subprocess.run(command, cwd=repo, env=env, stdout=output, stderr=subprocess.STDOUT)
    b = {'module': mod, 'command': command, 'returncode': result.returncode,
         'seconds': round(time.monotonic()-start, 3), 'log': str(log), 'log_sha256': sha(log)}
    if dest.exists():
        b['object_sha256'] = sha(dest)
    receipt['builds'].append(b)
    (overlay / 'dependency-replay.json').write_text(json.dumps(receipt, indent=2) + '\n')
    print('RESULT', mod, result.returncode, b['seconds'], flush=True)
    if result.returncode:
        print(log.read_text(), flush=True)
        raise SystemExit(result.returncode)
print('COMPLETE', overlay, flush=True)
